import struct, zlib, sys

def png_pixels(path):
    data = open(path, 'rb').read()
    off = 8
    w = h = bd = ct = None
    idat = b''
    while off < len(data):
        ln = struct.unpack('>I', data[off:off+4])[0]
        typ = data[off+4:off+8]
        body = data[off+8:off+8+ln]
        if typ == b'IHDR':
            w, h, bd, ct, comp, filt, inter = struct.unpack('>IIBBBBB', body)
        elif typ == b'IDAT':
            idat += body
        if typ == b'IEND':
            break
        off += 12 + ln
    raw = zlib.decompress(idat)
    channels = {0:1, 2:3, 4:2, 6:4}[ct]
    bpp = channels * bd // 8
    stride = w * bpp
    out = bytearray()
    prev = bytearray(stride)
    pos = 0
    for y in range(h):
        ft = raw[pos]; pos += 1
        line = bytearray(raw[pos:pos+stride]); pos += stride
        if ft == 1:
            for i in range(bpp, stride):
                line[i] = (line[i] + line[i-bpp]) & 255
        elif ft == 2:
            for i in range(stride):
                line[i] = (line[i] + prev[i]) & 255
        elif ft == 3:
            for i in range(stride):
                a = line[i-bpp] if i >= bpp else 0
                line[i] = (line[i] + (a + prev[i])//2) & 255
        elif ft == 4:
            for i in range(stride):
                a = line[i-bpp] if i >= bpp else 0
                b = prev[i]
                c = prev[i-bpp] if i >= bpp else 0
                p = a + b - c
                pa, pb, pc = abs(p-a), abs(p-b), abs(p-c)
                pr = a if (pa <= pb and pa <= pc) else (b if pb <= pc else c)
                line[i] = (line[i] + pr) & 255
        out += line
        prev = line
    return w, h, channels, out

def render(path, bw, bh, thresh=160):
    w, h, ch, px = png_pixels(path)
    # grayscale
    if ch == 4:
        gray = [int(0.299*px[i] + 0.587*px[i+1] + 0.114*px[i+2]) for i in range(0, len(px), 4)]
    elif ch == 3:
        gray = [int(0.299*px[i] + 0.587*px[i+1] + 0.114*px[i+2]) for i in range(0, len(px), 3)]
    else:
        gray = list(px)
    rows = []
    for y in range(0, h, bh):
        row = ''
        for x in range(0, w, bw):
            s = 0; n = 0
            for dy in range(bh):
                yy = y + dy
                if yy >= h: break
                for dx in range(bw):
                    xx = x + dx
                    if xx >= w: break
                    s += gray[yy*w + xx]; n += 1
            avg = s/n
            row += '#' if avg < thresh else '.'
        rows.append(row)
    return rows

if __name__ == '__main__':
    path = sys.argv[1]
    bw = int(sys.argv[2]); bh = int(sys.argv[3])
    thresh = int(sys.argv[4]) if len(sys.argv) > 4 else 160
    for r in render(path, bw, bh, thresh):
        print(r)

